final class Rater
{
    public const UNIT_PER_1M = 'per_1m_tokens';
    public const UNIT_UNIFIED = 'per_1m_tokens_unified';
    private const DIVISOR = '1000000';

    public static function baseCost(array $tokens, PriceRow $row): string // 'input','output','cache_read','cache_write' => int-string
    {
        if ($row->unit === self::UNIT_PER_1M) {
            $sum = '0';
            $sum = bcadd($sum, bcmul($tokens['input'], (string)$row->rateInput, Decimal::SCALE), Decimal::SCALE);
            ... 
            return bcdiv($sum, self::DIVISOR, Decimal::SCALE + 2);
        }
        if ($row->unit === self::UNIT_UNIFIED) {
            $total = tokens sum as int; 
            return bcdiv(bcmul((string)$total, rateAny, SCALE+2), DIVISOR, SCALE+2);
        }
        throw DomainException
    }

    public static function eventCost(array $tokens, PriceRow $row, ?OffPeakPolicy $op, DateTimeImmutable $ts): string
    {
        $cost = self::baseCost(...);
        if ($op && $op->covers($ts)) {
            $cost = bcmul($cost, $op->multiplier, Decimal::SCALE);
        }
        return Decimal::halfUp6($cost);
    }
}
