    public function run(): array  // [rated:int, unrated: array of UsageEvent]
    {
        return $this->em->transactional(function () {
            $events = $this->em->createQueryBuilder()->select('e')->from(UsageEvent::class,'e')->where('e.status = :st')->setParameter('st', 'pending')->orderBy('e.id','ASC')->getQuery()->getResult();
            if (!$events) return [0, []];

            // preload providers and models
            $providers = $this->em->getRepository(Provider::class)->findAll(); index by code
            $models = ... by index by providerId/code
            foreach ($events as $ev) {
                $provider = $providers[$ev->providerCode] ?? null;
                $providerId = $provider?->id;
                $model = $providerId !== null ? ($modelIndex["$providerId|".$ev->modelCode] ?? null) : null;
                $row = null;
                if ($model) { row = query price }
                if (!$row) { $unrated[] = $ev; continue; }
                $cost = Rater::eventCost($ev, $row, $provider?->offPeak(), $ev->ts);
                $ev->markRated($row->id, $cost, new DateTimeImmutable());
                $rated++;
