public function testDayWindow(): void
{
    $p = OffPeakPolicy::fromMinutes(16 * 60, 23 * 60 + 59, '0.5');

    self::assertFalse($p->covers(self::at('15:59')), '15:59 за окном');
    self::assertTrue($p->covers(self::at('16:00')), '16:00 — граница включена');
    self::assertTrue($p->covers(self::at('19:00')));
    self::assertTrue($p->covers(self::at('23:59')));
    self::assertFalse($p->covers(self::at('00:00')), '00:00 за окном');
}

public function testCrossMidnight(): void
{
    $p = OffPeakPolicy::fromMinutes(22 * 60 + 30, 1 * 60 + 30, '0.9');

    self::assertFalse($p->covers(self::at('22:29')));
    self::assertTrue($p->covers(self::at('22:30')));
    self::assertTrue($p->covers(self::at('00:15')));
    self::assertTrue($p->covers(self::at('01:30')));
    self::assertFalse($p->covers(self::at('01:31')));
}

public function testMultipliersAndSingleMinuteWindow(): void
{
    $p = OffPeakPolicy::fromMinutes(12 * 60, 12 * 60, '0.5'); // одноминутное окно
    self::assertSame('0.5', $p->multiplier());
    self::assertTrue($p->covers(self::at('12:00')));
    self::assertFalse($p->covers(self::at('12:01')));
}

